(type_code, type_name, type_description, extra_info)
VALUES
    ('RK_SYSANAL_2010H1_JC', '软考-系统分析师-2010年上半年-综合知识', '全国计算机技术与软件专业技术资格（水平）考试 系统分析师（高级） 2010年上半年 综合知识（来源：2010年上半年 系统分析师 详细答案.docx）', '{"source":"2010年上半年 系统分析师 详细答案.docx","exam":"系统分析师","year":"2010","term":"上半年","session":"综合知识","questionCount":6,"objectiveCount":6,"subjectiveCount":0,"resultMeanings":{},"scoring":{"resultMode":"objective_sum","scoreDimension":"score","maxScore":6,"scoringVersion":"1.0"}}')
